def owners_to_signatories(apps, schema_editor):
    """Every former Business.owner becomes the company's signatory (docs/data-model.md)."""
    Company = apps.get_model("business", "Company")
    Membership = apps.get_model("business", "Membership")
    for company in Company.objects.exclude(owner=None):
        Membership.objects.get_or_create(
            user_id=company.owner_id,
            company=company,
            defaults={"role": "signatory", "position": "Владелец"},
        )


